    sg.lineWidth=S*0.012*B;
    sg.beginPath();sg.moveTo(cxb+S*0.1,by+S*0.03);sg.lineTo(cxb+S*0.14,by+S*0.12);sg.stroke();
    sg.beginPath();sg.moveTo(cxb-S*0.13,by+S*0.03);sg.lineTo(cxb-S*0.2,by+S*0.13);sg.stroke();
